// <auto-generated/>

namespace Fanex.CustomerSetting.Module.SearchCopy.Services
{
    using Core.Models;
    using Criteria;
    using Entities;
    using Fanex.CustomerSetting.Module.Core.Criteria;
    using Fanex.CustomerSetting.Module.Core.Services.Impl;
    using Fanex.CustomerSetting.Module.Core.Services.Interface;
    using Fanex.Module.NG2.Repository;
    using Repositories;
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using System.Threading;
    using static Sunplus.Accounting.Core.Common.Enumerations;

    internal class SearchCopyService : ISearchCopyService
    {
        private readonly ISearchCopyRepository _searchCopyRepository;

        private readonly IServiceBase _serviceBase;

        public SearchCopyService(ISearchCopyRepository searchCopyRepository = null, IServiceBase serviceBase = null)
        {
            _searchCopyRepository = searchCopyRepository ?? new SearchCopyRepository();
            _serviceBase = serviceBase ?? new ServiceBase();
        }

        public SearchResult SearchExistingCustomer(string username, bool isMember)
        {
            var smaCustomers = _searchCopyRepository
                .GetSMACustomerInfo(new SearchExistingCustomerCriteria(username))
                .Where(smap => smap.CustId != 0);

            var searchResult = isMember
                ? BuildMemberSearchResult(username, smaCustomers)
                : BuildSuperSearchResult(username, smaCustomers);

            if (searchResult.CustId > 0)
            {
                var enableResult = _searchCopyRepository.ExecuteNonQuery(
                    new CheckCustomerEnabledCriteria(username));

                if (enableResult.IsSuccess)
                {
                    return searchResult;
                }
            }

            return new SearchResult();
        }

        private static SearchResult BuildSuperSearchResult(
            string username,
            IEnumerable<SMACustomerInfo> smaCustomers)
        {
            var super = smaCustomers.FirstOrDefault(smap =>
                smap.Username.Equals(username, StringComparison.OrdinalIgnoreCase)
                && smap.RoleId == 4);

            return super == null
                ? new SearchResult()
                : new SearchResult(super.CustId, 0, null);
        }

        private static SearchResult BuildMemberSearchResult(
            string username,
            IEnumerable<SMACustomerInfo> smaCustomers)
        {
            var smaCustomerList = smaCustomers.ToList();

            if (smaCustomerList.Count == 4)
            {
                var member = smaCustomerList[0];
                var agent = smaCustomerList[1];
                var master = smaCustomerList[2];
                var super = smaCustomerList[3];

                if (username.Equals(member.Username, StringComparison.OrdinalIgnoreCase))
                {
                    return new SearchResult(
                        member.CustId,
                        agent.CustId,
                        $"{super.Username} > {master.Username} > {agent.Username}");
                }
            }

            return new SearchResult();
        }

        public Hashtable GetSportBookSettingMember(int custId, int uplineId, int userId)
        {
            var sportbooksSetting = new Hashtable();

            var memberData = _searchCopyRepository.GetSportBookSettingMember(
                new GetSportBookSettingMemberCriteria(custId));

            if (memberData.Rows.Count > 0)
            {
                var settingCustomer = memberData.Rows[0];
                var checkConstraintData = new CheckConstraintDataForSportBook();

                checkConstraintData.GenerateInfoAccount(settingCustomer, custId, uplineId, userId, 0, ref sportbooksSetting);
                checkConstraintData.GenerateBettingLimit(settingCustomer, ref sportbooksSetting);
                checkConstraintData.GeneratePositionTaking(settingCustomer, ref sportbooksSetting);
            }

            return sportbooksSetting;
        }

        public CustomerInfo GetCustomerInfoByUserId(int custId, bool isMember, byte settingStatus)
        {
            var customerInfo = _searchCopyRepository.GetCustomerInfoByUserId(
                new GetCustomerInfoByUserIdCriteria(custId, isMember));

            var ng2Status = new NG2Service().GetStatus(custId, settingStatus);
            customerInfo.IsSyncNG2 = Convert.ToByte(ng2Status.IsSynced || (bool)BaseRepository.CheckAllowedCurrencyAll(custId, settingStatus).Outputs["allowedng2"]);
            customerInfo.DisableNG2 = Convert.ToByte(ng2Status.IsDisabled);

            return customerInfo;
        }

        public IEnumerable<Site> GetSitesExistingSuper(int userId)
            => _searchCopyRepository.GetSitesExistingSuper(new GetSitesCriteria(userId));

        public string CheckAvailableUsernames(string usernames)
        {
            var criteria = new GetExistingUsernameCriteria(usernames);
            var existingUsernames = _searchCopyRepository
                .GetExistingUsernames(criteria)
                .ToList();

            return existingUsernames.Count == 0
                ? string.Empty
                : $"Unavailable username(s): {string.Join(", ", existingUsernames)}";
        }

        public Result CopyMember(CopyExistingCustomerCriteria criteria, byte systemId, int fromSystem)
        {
            var sourceCustId = criteria.ExistingCustId;
            var uplineId = criteria.UplineId;
            var actorId = criteria.Creator;

            var customerInfo = GetSportBookSettingMember(sourceCustId, uplineId, actorId);
            customerInfo["username"] = criteria.UserName;
            customerInfo["userpwd"] = criteria.Userpwd;
            customerInfo["firstname"] = criteria.FirstName;
            customerInfo["lastname"] = criteria.LastName;
            customerInfo["phone"] = criteria.Phone;
            customerInfo["mobilephone"] = criteria.MobilePhone;
            customerInfo["fax"] = criteria.Fax;
            customerInfo["credit"] = criteria.Credit;
            customerInfo["custid"] = criteria.CustId;
            customerInfo["creator"] = actorId;
            customerInfo["userid"] = actorId;
            customerInfo["errcode"] = 0;
            customerInfo["errmsg"] = string.Empty;
            customerInfo["uplineid"] = uplineId;
            customerInfo["copyfromcustid"] = sourceCustId;
            customerInfo["isSearchAndCopy"] = 1;
            customerInfo["settingstatus"] = criteria.SettingStatus;

            var result = _searchCopyRepository.InsertMember(customerInfo);
            var custId = (int)customerInfo["custid"];

            if (result.IsSuccess)
            {
                criteria.CustId = custId;

                // Copy Keno.
                new KenoService().UpdateMemberData(custId, sourceCustId, actorId);

                // Copy DCS.
                new DCSSettingCopyInsertMemberService().CorrectMemberPositionTaking(custId, sourceCustId, actorId, criteria.IP, criteria.SettingStatus);

                Thread.Sleep(3000);

                var sourceCustInfo = GetCustomerInfoByUserId(sourceCustId, true, criteria.SettingStatus);

                // NG2.
                if (sourceCustInfo.IsSyncNG2 == 1)
                {
                    new NG2Service().SyncCustomer(criteria, systemId);
                }
            }

            return result;
        }

        public Result CopySuper(CopyExistingCustomerCriteria criteria, byte systemId, int fromSystem)
        {
            var result = _searchCopyRepository.CopyExistingSuper(criteria);

            if (result.IsSuccess)
            {
                _serviceBase.AddMsgAfterCreateNewSMA(new AddMsgAfterCreateNewSMACriteria(criteria.CustId, 0, (int)Role.Super));
                Thread.Sleep(3000);
                var sourceCustInfo = GetCustomerInfoByUserId(criteria.ExistingCustId, false, criteria.SettingStatus);

                // NG2.
                if (sourceCustInfo.IsSyncNG2 == 1)
                {
                    new NG2Service().SyncCustomer(criteria, systemId);
                }
            }

            return result;
        }
    }
}
